+        assert!(lme_rs::robust::compute_robust_se(&rounded, &data, None).is_ok());
+        rounded.fixed_design_x.as_mut().unwrap()[[0, 3]] += 128.0 * f64::EPSILON;
+        assert!(lme_rs::robust::compute_robust_se(&rounded, &data, None).is_err());
+    }
